using System;
using System.IO;
using Aurora.Engine;
namespace Aurora.Editor {
 public static class Tests {
  public static int Smoke(){try {var app=new System.Windows.Application();var p=Store.Create(Path.GetTempPath(),"AuroraSmoke-"+Guid.NewGuid(),"Learning");var window=new EditorWindow(p);window.Show();window.UpdateLayout();window.Dispatcher.Invoke(System.Windows.Threading.DispatcherPriority.Render,new Action(()=>{}));var image=new System.Windows.Media.Imaging.RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,System.Windows.Media.PixelFormats.Pbgra32);image.Render(window);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(image));using(var stream=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-preview.png")))encoder.Save(stream);window.Close();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"smoke-results.txt"),"PASS: WPF editor constructed, layout completed, 3D scene rendered to editor-preview.png");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"smoke-results.txt"),ex.ToString());return 1;}}
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
  public static int Run(){try{var root=Path.Combine(Path.GetTempPath(),"AuroraTests-"+Guid.NewGuid());var p=Store.Create(root,"Test","Learning");var s=Store.LoadScene(p.ScenePath);Check(s.Entities.Count==3,"template");var child=new Entity{Parent=s.Entities[1].Id,Name="Child",X=3};s.Entities.Add(child);Store.Save(p.ScenePath,s);var loaded=Store.LoadScene(Store.Open(Path.Combine(p.Root,"project.aurora")).ScenePath);Check(loaded.Entities[3].Parent==child.Parent,"hierarchy persistence");var runtime=new Runtime(s);runtime.Tick(.02,0,0);Check(runtime.Scene.Entities[1].RY>0&&s.Entities[1].RY==0,"runtime isolation");s.Entities[1].Components.Add(new Component{Type="Controller",Value=3});runtime=new Runtime(s);runtime.Tick(.05,1,0);Check(Math.Abs(runtime.Scene.Entities[1].X-.15)<.00001,"controller");s.Entities[1].Parent=child.Id;bool rejected=false;try{s.Validate();}catch{rejected=true;}Check(rejected,"cycle validation");s.Entities[1].Parent=null;s.Delete(s.Entities[1].Id);Check(s.Entities.Count==2,"recursive delete");Check(File.Exists(p.ScenePath+".bak"),"atomic backup");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),"PASS: templates, JSON persistence, hierarchy, runtime isolation, controller, cycle validation, recursive delete, atomic backup\nTest project: "+p.Root);return 0;}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),e.ToString());return 1;}}
 }
}
